use crate::{foveate_rgb8_with_map,qp_delta_map};
use crate::types::FoveationConfig;
use std::slice;
#[no_mangle] pub unsafe extern "C" fn fs_foveate_rgb8(src:*const u8,width:usize,height:usize,quality:*const f32,cfg:*const FoveationConfig,dst:*mut u8)->i32{if src.is_null()||quality.is_null()||cfg.is_null()||dst.is_null()||width==0||height==0{return -1;}let pixels=match width.checked_mul(height){Some(v)=>v,None=>return -2};let bytes=match pixels.checked_mul(3){Some(v)=>v,None=>return -2};let src=slice::from_raw_parts(src,bytes);let q=slice::from_raw_parts(quality,pixels);let out=foveate_rgb8_with_map(src,width,height,q,&*cfg);if out.len()!=bytes{return -3;}std::ptr::copy_nonoverlapping(out.as_ptr(),dst,bytes);0}
#[no_mangle] pub unsafe extern "C" fn fs_qp_delta_map(quality:*const f32,width:usize,height:usize,block:usize,fovea_delta:i8,periphery_delta:i8,dst:*mut i8,dst_len:usize)->isize{if quality.is_null()||dst.is_null()||width==0||height==0||block==0{return -1;}let pixels=match width.checked_mul(height){Some(v)=>v,None=>return -2};let q=slice::from_raw_parts(quality,pixels);let out=qp_delta_map(q,width,height,block,fovea_delta,periphery_delta);if dst_len<out.len(){return -(out.len() as isize);}std::ptr::copy_nonoverlapping(out.as_ptr(),dst,out.len());out.len() as isize}
